-- Import Master Bahan (201 bahan). Aman dijalankan berulang: bahan dengan nama+satuan
-- yang sama (tidak peka huruf besar/kecil) dilewati, kode BHN-### dilanjutkan otomatis
-- dari nomor terbesar yang sudah ada. Jalankan lewat phpMyAdmin > tab SQL (pilih database dulu).
SET NAMES utf8mb4;
SET @n := (SELECT COALESCE(MAX(CAST(SUBSTRING(kode, 5) AS UNSIGNED)), 0) FROM materials WHERE kode REGEXP '^BHN-[0-9]+$');


SELECT COUNT(*) AS total_bahan FROM materials;
